const SEP = '\u001F';

return items.map(({ json }) => {
  // Parse JSON string from Google Sheet cell
  const kv = typeof json.sentences === 'string' ? JSON.parse(json.sentences) : json.sentences;

  // Rebuild arrays
  const sentences = {};
  for (const [lang, joined] of Object.entries(kv || {})) {
    sentences[lang] = (joined ?? '').split(SEP);
  }

  // Only return the sentences object
  return { json: { sentences } };
});
